#nullable enable

using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Threading;
using Campground.Shared.Registry;

namespace Campground.Shared.Storage
{
    /// <summary>A file that was too big to load or write.</summary>
    internal sealed class StorageLimitException : IOException
    {
        internal StorageLimitException(string message)
            : base(message)
        {
        }
    }

    /// <summary>
    /// One migration step: takes the document at <see cref="FromVersion"/> and returns it at FromVersion + 1.
    /// </summary>
    internal sealed record Migration(int FromVersion, Func<JsonObject, JsonObject> Apply);

    /// <summary>
    /// JSON on disk that's never half-written: write to a temp file, flush, then replace. Keeps one ".bak".
    /// Documents carry a <c>"schemaVersion"</c> and are migrated forward on load. Size-capped both ways.
    /// </summary>
    internal sealed class AtomicJsonFile
    {
        internal const string VersionField = "schemaVersion";

        /// <summary>Default cap: 8 MiB.</summary>
        internal const long DefaultMaxBytes = 8L * 1024 * 1024;

        private static readonly JsonSerializerOptions Indented = new(CampgroundRegistry.Json) { WriteIndented = true };

        // Temp files older than this are left over from a crash; a younger one may be a writer still at work.
        private static readonly TimeSpan OrphanAge = TimeSpan.FromHours(1);

        private readonly object _gate;
        private readonly IReadOnlyList<Migration> _migrations;

        internal AtomicJsonFile(string path, int currentVersion = 1, IReadOnlyList<Migration>? migrations = null, long maxBytes = DefaultMaxBytes)
        {
            // Every plugin compiles its own copy of this class, so a lock held in a static would not be shared.
            // The registry holds one plain object per file, which every copy in the process finds.
            var key = Path.GetFullPath(path);
            if (!OperatingSystem.IsLinux())
            {
                key = key.ToUpperInvariant();
            }

            _gate = CampgroundRegistry.Section("atomicfile.locks").GetOrAdd(key, _ => new object());
            FilePath = path;
            CurrentVersion = currentVersion;
            MaxBytes = maxBytes;
            _migrations = migrations ?? Array.Empty<Migration>();
        }

        internal string FilePath { get; }

        internal int CurrentVersion { get; }

        internal long MaxBytes { get; }

        /// <summary>Loads and migrates; returns null when the file doesn't exist. Falls back to the .bak if the main file is corrupt.</summary>
        internal T? Load<T>()
            where T : class
        {
            // A main file that parses but doesn't fit T is as unusable as a corrupt one: try the backup.
            JsonException? failed = null;
            foreach (var candidate in new[] { FilePath, FilePath + ".bak" })
            {
                var node = ReadCandidate(candidate);
                if (node == null)
                {
                    continue;
                }

                try
                {
                    return node.Deserialize<T>(CampgroundRegistry.Json);
                }
                catch (JsonException ex)
                {
                    failed = ex;
                }
            }

            return failed == null ? null : throw failed;
        }

        /// <summary>Loads as a JSON object (migrated), or null.</summary>
        internal JsonObject? LoadNode()
        {
            foreach (var candidate in new[] { FilePath, FilePath + ".bak" })
            {
                if (ReadCandidate(candidate) is { } node)
                {
                    return node;
                }
            }

            return null;
        }

        // The file as a migrated object, or null when it is missing or isn't a JSON object.
        private JsonObject? ReadCandidate(string candidate)
        {
            lock (_gate)
            {
                if (!File.Exists(candidate))
                {
                    return null;
                }

                var info = new FileInfo(candidate);
                if (info.Length > MaxBytes)
                {
                    throw new StorageLimitException($"{candidate} is {info.Length} bytes; the limit is {MaxBytes}.");
                }

                try
                {
                    return JsonNode.Parse(File.ReadAllText(candidate)) is JsonObject obj ? Migrate(obj) : null;
                }
                catch (JsonException)
                {
                    return null;
                }
            }
        }

        private bool MainFileParses()
        {
            try
            {
                return File.Exists(FilePath) && JsonNode.Parse(File.ReadAllText(FilePath)) is JsonObject;
            }
            catch (Exception ex) when (ex is JsonException or IOException or UnauthorizedAccessException)
            {
                return false;
            }
        }

        private void RemoveOrphans(string dir)
        {
            try
            {
                var prefix = "." + Path.GetFileName(FilePath) + ".";
                foreach (var f in Directory.EnumerateFiles(dir, prefix + "*.tmp"))
                {
                    if (DateTime.UtcNow - File.GetLastWriteTimeUtc(f) > OrphanAge)
                    {
                        File.Delete(f);
                    }
                }
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                // Clean-up only: a file somebody else holds is left for the next save.
            }
        }

        /// <summary>Saves atomically.</summary>
        internal void Save<T>(T value)
        {
            var node = JsonSerializer.SerializeToNode(value, CampgroundRegistry.Json) as JsonObject
                ?? throw new ArgumentException("The value must serialise to a JSON object.", nameof(value));
            SaveNode(node);
        }

        /// <summary>Saves a JSON object atomically, stamping the schema version.</summary>
        internal void SaveNode(JsonObject node)
        {
            node[VersionField] = CurrentVersion;
            var bytes = JsonSerializer.SerializeToUtf8Bytes(node, Indented);
            if (bytes.LongLength > MaxBytes)
            {
                throw new StorageLimitException($"Refusing to write {bytes.LongLength} bytes to {FilePath}; the limit is {MaxBytes}.");
            }

            lock (_gate)
            {
                var dir = Path.GetDirectoryName(Path.GetFullPath(FilePath))!;
                Directory.CreateDirectory(dir);
                var temp = Path.Combine(dir, "." + Path.GetFileName(FilePath) + "." + Guid.NewGuid().ToString("N") + ".tmp");
                try
                {
                    using (var fs = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None))
                    {
                        fs.Write(bytes, 0, bytes.Length);
                        fs.Flush(flushToDisk: true);
                    }

                    if (File.Exists(FilePath) && MainFileParses())
                    {
                        ReplaceWithRetry(temp, FilePath, FilePath + ".bak");
                    }
                    else
                    {
                        // No main file, or one that is corrupt: keep the .bak as it is rather than copy the bad file over it.
                        File.Move(temp, FilePath, overwrite: true);
                    }

                    RemoveOrphans(dir);
                }
                finally
                {
                    if (File.Exists(temp))
                    {
                        File.Delete(temp);
                    }
                }
            }
        }

        /// <summary>Deletes the file and its backup.</summary>
        internal void Delete()
        {
            lock (_gate)
            {
                File.Delete(FilePath);
                File.Delete(FilePath + ".bak");
            }
        }

        private JsonObject Migrate(JsonObject obj)
        {
            var version = obj[VersionField] is JsonValue v && v.TryGetValue<int>(out var n) ? n : 1;
            if (version > CurrentVersion)
            {
                // Written by a newer plugin: keep it as is, never downgrade data.
                return obj;
            }

            while (version < CurrentVersion)
            {
                var step = FindStep(version)
                    ?? throw new InvalidOperationException($"{FilePath}: no migration from schema version {version}.");
                obj = step.Apply(obj);
                version++;
                obj[VersionField] = version;
            }

            return obj;
        }

        private Migration? FindStep(int from)
        {
            foreach (var m in _migrations)
            {
                if (m.FromVersion == from)
                {
                    return m;
                }
            }

            return null;
        }

        private static void ReplaceWithRetry(string source, string destination, string backup)
        {
            // Antivirus and indexers briefly hold files on Windows; retry a few times.
            for (var attempt = 0; ; attempt++)
            {
                try
                {
                    File.Replace(source, destination, backup, ignoreMetadataErrors: true);
                    return;
                }
                catch (IOException) when (attempt < 4)
                {
                    Thread.Sleep(50 * (attempt + 1));
                }
                catch (PlatformNotSupportedException)
                {
                    File.Copy(destination, backup, overwrite: true);
                    File.Move(source, destination, overwrite: true);
                    return;
                }
            }
        }
    }
}
